-- Written by tools/herbalore.py from lines.tsv; edit those, not this.
local _, ns = ...
ns.HERBS = {
    ["Peacebloom"] = { { "peacebloom", "Peacebloom. The first herb most healers ever learn to pick. It asks nothing of you, and it grows wherever there is a little peace to spare." }, { "peacebloom_2", "Peacebloom again. Some druids keep one pressed in their satchel, just to remember where they started." }, { "peacebloom_3", "Small, white, and everywhere. The world is generous with the gentle things, if you look." } },
    ["Silverleaf"] = { { "silverleaf", "Silverleaf. Turn it in the light and you'll see why it has the name. Small things are worth noticing." }, { "silverleaf_2", "Silverleaf likes the edges of paths. It has watched more travellers pass than any of us." }, { "silverleaf_3", "Hold it up to the moon sometime. It glows almost the same colour." } },
    ["Earthroot"] = { { "earthroot", "Earthroot. It likes the feet of hills and the shelter of stones. Steady, patient, and holding on." }, { "earthroot_2", "Earthroot never hurries. It takes its time, and it takes hold." }, { "earthroot_3", "Brush the soil from it gently. The hills gave it up for you." } },
    ["Mageroyal"] = { { "mageroyal", "Mageroyal. A proud little flower, for one that grows by the roadside." }, { "mageroyal_2", "Mageroyal. Bright as a little flame, and just as eager." }, { "mageroyal_3", "A royal name for a roadside flower. It doesn't seem to mind which." } },
    ["Briarthorn"] = { { "briarthorn", "Briarthorn. Mind your fingers. Even the thorns are only keeping something safe." }, { "briarthorn_2", "Briarthorn guards itself. Gloves, or patience. Patience is better." }, { "briarthorn_3", "Even the thorny ones are worth the care. Most good things are." } },
    ["Swiftthistle"] = { { "swiftthistle", "Swiftthistle. It hides among other herbs and comes to you as a small surprise. The alchemists make swiftness from it." }, { "swiftthistle_2", "Swiftthistle hides in the shade of other herbs. A small gift for those who look twice." }, { "swiftthistle_3", "Quick to find, quick to fade. Enjoy it while it's here." } },
    ["Bruiseweed"] = { { "bruiseweed", "Bruiseweed. An ugly name for a plant that helps things mend." }, { "bruiseweed_2", "A dusty leaf from a dusty slope. The healers will turn it into comfort." }, { "bruiseweed_3", "It grows in the hard places, between rocks. Stubborn and kind at once." } },
    ["Stranglekelp"] = { { "stranglekelp", "Stranglekelp. The sea keeps its own garden. Take a breath before you go down for it." }, { "stranglekelp_2", "Kelp, swaying in the current like a slow green dance. Watch it a moment before you take some." }, { "stranglekelp_3", "Cold and green and swaying. Even underwater, the world breathes." } },
    ["Wild Steelbloom"] = { { "wild_steelbloom", "Wild Steelbloom. A flower that decided to be as tough as the hills around it." }, { "wild_steelbloom_2", "Steel in the name, petals in the hand. It's allowed to be both." }, { "wild_steelbloom_3", "It grows where the ground is hard. It doesn't complain about it." } },
    ["Grave Moss"] = { { "grave_moss", "Grave Moss. It grows where the dead are laid. Pick it gently. Someone was remembered here." }, { "grave_moss_2", "Grave Moss. Life, even here. Especially here." }, { "grave_moss_3", "Pick it softly. Whoever rests beneath won't mind a little company." } },
    ["Kingsblood"] = { { "kingsblood", "Kingsblood. A grand name for a quiet plant. Kings come and go. The herb is still here." }, { "kingsblood_2", "Kingsblood. Deep red, and proud of it. Every herb has its own way of standing tall." }, { "kingsblood_3", "A royal name for a wild thing. It answers to no king at all." } },
    ["Liferoot"] = { { "liferoot", "Liferoot. It follows the water, and drinks from the riverbanks. Where it grows, things are alive." }, { "liferoot_2", "The sound of running water, and there it is. Liferoot never strays far from a river." }, { "liferoot_3", "Its name says everything. Life, and roots. What more do any of us need?" } },
    ["Fadeleaf"] = { { "fadeleaf", "Fadeleaf. It prefers the shade, and it's easy to walk past. Most of the best things are." }, { "fadeleaf_2", "Fadeleaf. Look away and it's half gone. Look back, and it was always there." }, { "fadeleaf_3", "Rogues love it for hiding. You can love it for being quietly lovely." } },
    ["Goldthorn"] = { { "goldthorn", "Goldthorn. It catches the evening light on the hillsides. Take a moment to watch it." }, { "goldthorn_2", "Goldthorn. Gold that grows. The only kind worth having, really." }, { "goldthorn_3", "A thorn with a golden edge. Careful hands, and it gives itself up easily." } },
    ["Khadgar's Whisker"] = { { "khadgars_whisker", "Khadgar's Whisker. Named for the archmage, and said to look a little like his beard. Even legends end up as herbs, eventually." }, { "khadgars_whisker_2", "Khadgar's Whisker. Named for a wizard, but it was here first." }, { "khadgars_whisker_3", "Thin and wiry and wise-looking. It suits the name." } },
    ["Wintersbite"] = { { "wintersbite", "Wintersbite. It only grows in the cold of the Alterac Mountains. It bites back, a little." }, { "wintersbite_2", "Wintersbite. It blooms in the cold because nobody told it not to." }, { "wintersbite_3", "Frost on the petals and a bite in the air. Wrap up warm." } },
    ["Firebloom"] = { { "firebloom", "Firebloom. It loves the hottest, driest lands, where little else will grow." }, { "firebloom_2", "Firebloom. It drinks the heat and gives back colour." }, { "firebloom_3", "Where the ground is scorched, it grows anyway. A little hope in a hard place." } },
    ["Purple Lotus"] = { { "purple_lotus", "Purple Lotus. A lotus that grows out of hard country. Beautiful things don't always need soft ground." }, { "purple_lotus_2", "Purple Lotus. It floats like it has nowhere to be. Take the hint." }, { "purple_lotus_3", "Lotus petals open slowly. There's no rushing a flower." } },
    ["Arthas' Tears"] = { { "arthas_tears", "Arthas' Tears. It grows where the plague passed through. Even grief can flower, given long enough." }, { "arthas_tears_2", "A pale little flower with a heavy name. It didn't choose the name. It only chose to grow." }, { "arthas_tears_3", "They grow where the land was hurt. The land remembers, and it heals anyway." } },
    ["Sungrass"] = { { "sungrass", "Sungrass. It spreads across open land under a wide sky. Stand up straight for a moment, and feel the sun." }, { "sungrass_2", "Sungrass. It holds the light of long afternoons. Take some with you." }, { "sungrass_3", "Warm to the touch, almost. As if it's been listening to the sun all day." } },
    ["Blindweed"] = { { "blindweed", "Blindweed. A plant of the swamps and the deep wet places. The marsh is full of life, if you're slow enough to see it." }, { "blindweed_2", "Frogs, reeds, the smell of wet earth. Blindweed's home is a busy one." }, { "blindweed_3", "Careful in the mire. Step where the roots are; they know the ground." } },
    ["Ghost Mushroom"] = { { "ghost_mushroom", "Ghost Mushroom. It glows faintly in the dark places. Even down here, something is growing." }, { "ghost_mushroom_2", "Ghost Mushroom. A little lantern for the dark places." }, { "ghost_mushroom_3", "Quiet down here. The mushrooms keep the caves company." } },
    ["Gromsblood"] = { { "gromsblood", "Gromsblood. Named for Grom Hellscream, who fell, and rose, and paid for it. The land remembers him in red." }, { "gromsblood_2", "Gromsblood. A fierce name. It grows where the land is wounded, and it still grows." }, { "gromsblood_3", "Dark and bitter. Not every gift is gentle, but it is still a gift." } },
    ["Golden Sansam"] = { { "golden_sansam", "Golden Sansam. Warm in the hand, and worth the walk. The healers prize it." }, { "golden_sansam_2", "Golden Sansam. A warm colour for a warm place. Breathe it in." }, { "golden_sansam_3", "Some herbs ask to be found. Sansam just waits, glowing." } },
    ["Dreamfoil"] = { { "dreamfoil", "Dreamfoil. Some say it carries a little of the Emerald Dream in its leaves. A druid would know." }, { "dreamfoil_2", "The druids who sleep in the barrow dens walk the Dream for years. A leaf of it is plenty for one afternoon." }, { "dreamfoil_3", "Pick it gently, as if you might wake it." } },
    ["Mountain Silversage"] = { { "mountain_silversage", "Mountain Silversage. It grows high, where the air is thin and clean. Breathe it in." }, { "mountain_silversage_2", "Mountain Silversage. Worth the climb. Turn round, if you like, and see how far you've come." }, { "mountain_silversage_3", "Silver in the leaves and snow in the wind. Worth every step." } },
    ["Plaguebloom"] = { { "plaguebloom", "Plaguebloom. It grows from tainted ground and turns that taint into medicine. Healing often starts in the worst places." }, { "plaguebloom_2", "Plaguebloom. The soil is sick, but the flower still opens. The land is fighting for itself." }, { "plaguebloom_3", "Every one you pick is one less sorrow in the soil." } },
    ["Icecap"] = { { "icecap", "Icecap. A flower of Winterspring's snow. It has learned how to bloom in the cold." }, { "icecap_2", "Icecap. It grows under the snow, waiting. Patience made into a plant." }, { "icecap_3", "Cold fingers, warm heart. That's how you gather Icecap." } },
    ["Black Lotus"] = { { "black_lotus", "Black Lotus. The rarest flower in Azeroth. Hold it for a moment before you put it away. You may not see another for a long time." }, { "black_lotus_2", "Another Black Lotus. Luck like this deserves a quiet moment of thanks." }, { "black_lotus_3", "Darker than the night sky, and just as full of stars, if you look closely." } },
}
ns.CALM = {
    { "calm1", "Breathe. The forest isn't going anywhere, and neither is the next herb." },
    { "calm2", "Listen for a moment. Wind, birds, water. You're allowed to just be here." },
    { "calm3", "You don't have to hurry. Gathering is a kind of listening." },
    { "calm4", "Look up from the map, if you like. Somewhere nearby, something beautiful is happening that nobody else will see." },
    { "calm5", "Every herb you pick will grow back. That's the oldest lesson in the druid's path." },
    { "calm6", "The world is big, and you are in it. That's enough for today." },
    { "calm7", "Kneel. Pick slowly. Say thank you, if you like. The druids always did." },
    { "calm8", "The roots go deeper than you can see. Somewhere under your feet, the whole forest is holding hands." },
    { "calm9", "Your hands know this path now. Let them. The rest of you can simply look around." },
    { "calm10", "Picking, walking, picking. A rhythm like this can hold a busy mind, if you let it." },
}
ns.SKIN = {
    { "skin1", "Thank you, little one. Nothing of you will be wasted." },
    { "skin2", "Every hunt is a debt. Carry it lightly, and use it well." },
    { "skin3", "Gently now. The beast has given what it had. Its spirit runs on, somewhere green and quiet." },
    { "skin4", "In a few days this will be a cloak, or a quiver. And still, somehow, a little bit wild." },
    { "skin5", "The kaldorei never took more than the forest could spare. Neither do you." },
    { "skin6", "Rest now, friend. The forest will take back what's left." },
}
